begin;
create function test_support.draft_payload(p_reverse boolean default false) returns jsonb language sql as $$
 select jsonb_agg(jsonb_build_object('id',test_support.id('dq'||i),'question_text','Draft question '||i,'question_type','multiple_choice',
 'choices',jsonb_build_array(jsonb_build_object('id',test_support.id('dc'||i||'a'),'choice_text','A'),jsonb_build_object('id',test_support.id('dc'||i||'b'),'choice_text','B'))) order by case when p_reverse then -i else i end)
 from generate_series(1,2) i;
$$;
set local role anon;
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),null,test_support.id('request1'),'Title',null,'[]')$q$,'42501','permission denied');
set local role authenticated;
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),null,test_support.id('request1'),'Title',null,'[]')$q$,'42501','AUTHENTICATION_REQUIRED');
select set_config('request.jwt.claim.sub',test_support.id('instructor')::text,true);
select set_config('test.save1',public.save_draft_survey(test_support.id('draft'),null,test_support.id('request1'),'Title',null,test_support.draft_payload())::text,true);
select test_support.check((select count(*)=2 from public.questions where survey_id=test_support.id('draft')),'atomic create stores all questions');
select test_support.check((select count(*)=4 from public.choices),'atomic create stores all choices');
select test_support.check(public.save_draft_survey(test_support.id('draft'),null,test_support.id('request1'),'Title',null,test_support.draft_payload())=current_setting('test.save1')::jsonb,'lost-response retry returns same result without duplicate creation');
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),null,test_support.id('request1'),'Different',null,test_support.draft_payload())$q$,'P0001','SAVE_REQUEST_REUSED');
select set_config('test.save2',public.save_draft_survey(test_support.id('draft'),(current_setting('test.save1')::jsonb->>'updated_at')::timestamptz,test_support.id('request2'),'Reordered',null,test_support.draft_payload(true))::text,true);
select test_support.check((select id=test_support.id('dq2') from public.questions where survey_id=test_support.id('draft') and position=1),'question reorder preserves IDs');
select test_support.check((select updated_at=(current_setting('test.save2')::jsonb->>'updated_at')::timestamptz from public.surveys where id=test_support.id('draft')),'returned version includes child edits');
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),(current_setting('test.save1')::jsonb->>'updated_at')::timestamptz,test_support.id('stale'),'Stale overwrite',null,test_support.draft_payload())$q$,'P0001','DRAFT_CONFLICT');
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),null,test_support.id('request1'),'Title',null,test_support.draft_payload())$q$,'P0001','DRAFT_CONFLICT');
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),(current_setting('test.save2')::jsonb->>'updated_at')::timestamptz,test_support.id('blank'),'   ',null,test_support.draft_payload())$q$,'P0001','INVALID_DRAFT');
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),(current_setting('test.save2')::jsonb->>'updated_at')::timestamptz,test_support.id('duplicate'),'Duplicate',null,jsonb_build_array(test_support.draft_payload()->0,test_support.draft_payload()->0))$q$,'P0001','DUPLICATE_DRAFT_ID');
select test_support.check((select title='Reordered' from public.surveys where id=test_support.id('draft')),'validation failures preserve old metadata');
select test_support.throws($q$select * from private.draft_save_receipts$q$,'42501','permission denied');
reset role;
create function test_support.fail_choice_save() returns trigger language plpgsql as $$ begin raise exception 'TEST_CHOICE_WRITE_FAILED'; end $$;
create trigger test_choice_write before insert on public.choices for each row execute function test_support.fail_choice_save();
set local role authenticated;
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),(current_setting('test.save2')::jsonb->>'updated_at')::timestamptz,test_support.id('rollback'),'Should roll back',null,test_support.draft_payload())$q$,'P0001','TEST_CHOICE_WRITE_FAILED');
select test_support.check((select title='Reordered' and updated_at=(current_setting('test.save2')::jsonb->>'updated_at')::timestamptz from public.surveys where id=test_support.id('draft')),'late write failure rolls metadata and version back');
select test_support.check((select count(*)=4 from public.choices),'late write failure preserves choices');
reset role;
drop trigger test_choice_write on public.choices;
set local role authenticated;
select set_config('test.save3',public.save_draft_survey(test_support.id('draft'),(current_setting('test.save2')::jsonb->>'updated_at')::timestamptz,test_support.id('request3'),'Choice order',null,jsonb_set(jsonb_build_array(test_support.draft_payload()->0),'{0,choices}',jsonb_build_array(test_support.draft_payload()->0->'choices'->1,test_support.draft_payload()->0->'choices'->0)))::text,true);
select test_support.check((select count(*)=1 from public.questions where survey_id=test_support.id('draft')) and (select count(*)=2 from public.choices),'omitted question and its choices deleted atomically');
select test_support.check((select id=test_support.id('dc1b') from public.choices where question_id=test_support.id('dq1') and position=1),'choice reorder preserves IDs');
update public.choices set choice_text='Direct draft edit' where id=test_support.id('dc1b');
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),(current_setting('test.save3')::jsonb->>'updated_at')::timestamptz,test_support.id('stale-child'),'Stale',null,test_support.draft_payload())$q$,'P0001','DRAFT_CONFLICT');
select public.save_draft_survey(test_support.id('incomplete'),null,test_support.id('incomplete-request'),'Incomplete draft',null,'[]');
select test_support.throws($q$select public.activate_survey(test_support.id('incomplete'))$q$,'P0001','SURVEY_REQUIRES_QUESTIONS');
select test_support.throws($q$select public.save_draft_survey(test_support.id('other'),null,test_support.id('cross'),'Cross survey',null,jsonb_build_array(test_support.draft_payload()->0))$q$,'P0001','INVALID_QUESTION');
select public.activate_survey(test_support.id('draft'));
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),now(),test_support.id('active-save'),'Active',null,'[]')$q$,'P0001','DRAFT_ONLY_EDITING');
select public.close_survey(test_support.id('draft'));
select test_support.throws($q$select public.save_draft_survey(test_support.id('draft'),now(),test_support.id('closed-save'),'Closed',null,'[]')$q$,'P0001','DRAFT_ONLY_EDITING');
delete from public.surveys where id=test_support.id('draft');
reset role;
select test_support.check(not exists(select 1 from private.draft_save_receipts where survey_id=test_support.id('draft')),'deletion also removes private retry receipts');
rollback;
